create extension if not exists pgcrypto;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,role text not null default 'viewer' check(role in('admin','viewer')),display_name text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.event_categories(id uuid primary key default gen_random_uuid(),code text not null unique,name text not null,icon text,sort_order integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.members(id uuid primary key default gen_random_uuid(),display_name text not null,canonical_name text not null unique,avatar_url text,description text,current_status text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.events(id uuid primary key default gen_random_uuid(),title text not null,event_year integer not null check(event_year between 1900 and 2200),event_month integer check(event_month between 1 and 12),event_day integer check(event_day between 1 and 31),date_precision text not null default 'day' check(date_precision in('day','month','early_month','mid_month','late_month','year','unknown')),date_text text,category_id uuid not null references public.event_categories(id) on delete restrict,summary text not null default '',content text,location text,importance smallint not null default 1 check(importance between 1 and 5),is_featured boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references auth.users(id),updated_by uuid references auth.users(id),constraint valid_date_precision check((date_precision='day' and event_month is not null and event_day is not null) or (date_precision in('month','early_month','mid_month','late_month') and event_month is not null and event_day is null) or (date_precision in('year','unknown') and event_day is null)));
create table public.event_members(id uuid primary key default gen_random_uuid(),event_id uuid not null references public.events(id) on delete cascade,member_id uuid not null references public.members(id) on delete restrict,role text,note text,created_at timestamptz not null default now(),unique(event_id,member_id));
create table public.event_images(id uuid primary key default gen_random_uuid(),event_id uuid not null references public.events(id) on delete cascade,storage_path text not null unique,caption text,sort_order integer not null default 0,uploaded_by uuid references auth.users(id),created_at timestamptz not null default now());
create table public.event_revisions(id uuid primary key default gen_random_uuid(),event_id uuid not null references public.events(id) on delete cascade,revision_number integer not null,snapshot jsonb not null,edited_by uuid references auth.users(id),edited_at timestamptz not null default now(),unique(event_id,revision_number));
create index idx_events_year on public.events(event_year);create index idx_events_month on public.events(event_month);create index idx_events_category on public.events(category_id);create index idx_events_featured on public.events(is_featured);create index idx_events_importance on public.events(importance);create index idx_event_members_event on public.event_members(event_id);create index idx_event_members_member on public.event_members(member_id);create index idx_event_images_event on public.event_images(event_id);create index idx_event_revisions_event on public.event_revisions(event_id);
create function public.set_updated_at() returns trigger language plpgsql set search_path=public as $$begin new.updated_at=now();return new;end$$;create trigger events_updated before update on public.events for each row execute function public.set_updated_at();create trigger members_updated before update on public.members for each row execute function public.set_updated_at();create trigger categories_updated before update on public.event_categories for each row execute function public.set_updated_at();
